// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
class CountingSink : public ImportSink
{
public:
    std::size_t    rows   = 0;
    std::streamoff offset = 0;

    bool store( const std::vector<Measurement> & batch, std::streamoff new_offset ) override
    {
        rows += batch.size();
        offset = new_offset;
        return true;
    }
};
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0

