// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
std::string file_mtime( const std::string & file )
{
    struct stat st;

    if( ::stat( file.c_str(), &st ) != 0 ) {
        return std::string();
    }

    struct tm tmv;
    if( !localtime_r( &st.st_mtime, &tmv ) ) {
        return std::string();
    }

    char buf[ 32 ];
    std::strftime( buf, sizeof( buf ), "%Y-%m-%d %H:%M:%S", &tmv );
    return buf;
}
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0

// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
std::streamoff file_size( const std::string & file )
{
    struct stat st;

    if( ::stat( file.c_str(), &st ) != 0 ) {
        return 0;
    }

    return (std::streamoff)st.st_size;
}
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0

// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
void print_result( ColoredOutput & co, const std::string & file,
                   std::streamoff start_offset, const ImportResult & res,
                   const std::string & error )
{
    std::cout << "file      : " << file << '\n'
              << "offset    : " << (long long)start_offset
              << " -> " << (long long)res.new_offset << '\n'
              << "lines     : " << res.lines << '\n'
              << "records   : " << res.records << '\n'
              << "empty     : " << res.empty << '\n'
              << "malformed : " << res.malformed << '\n';

    if( !error.empty() ) {
        std::cout << "error     : "
                  << co.color_output( ColoredOutput::BRIGHT_RED, error ) << '\n';
    }

    std::cout << "result    : "
              << co.color_output( res.ok ? ColoredOutput::GREEN : ColoredOutput::RED,
                                  res.ok ? "ok" : "failed" )
              << std::endl;
}
