int main( int argc, char ** argv )
{
    ColoredOutput co;

    Arg::Arg arg( argc, argv );
    arg.addPrefix( "-" );
    arg.addPrefix( "--" );

    Arg::OptionChain oc_info;
    arg.addChainR( &oc_info );
    oc_info.setMinMatch( 1 );
    oc_info.setContinueOnMatch( false );
    oc_info.setContinueOnFail( true );

    Arg::FlagOption o_help( "h" );
    o_help.addName( "help" );
    o_help.setDescription( "show this page" );
    oc_info.addOptionR( &o_help );

    Arg::StringOption o_config( "c" );
    o_config.addName( "config" );
    o_config.setValueDescription( "file" );
    o_config.setDescription( "ini file (database and import sections)" );
    o_config.setRequired( false );
    arg.addOptionR( &o_config );

    Arg::StringOption o_host( "H" );
    o_host.addName( "host" );
    o_host.setDescription( "mysql host (default: localhost)" );
    o_host.setRequired( false );
    arg.addOptionR( &o_host );

    Arg::StringOption o_user( "u" );
    o_user.addName( "user" );
    o_user.setDescription( "mysql user" );
    o_user.setRequired( false );
    arg.addOptionR( &o_user );

    Arg::StringOption o_password( "p" );
    o_password.addName( "password" );
    o_password.setDescription( "mysql password (default: $PI_SENSOR_DB_PASSWORD)" );
    o_password.setRequired( false );
    arg.addOptionR( &o_password );

    Arg::StringOption o_database( "D" );
    o_database.addName( "database" );
    o_database.setDescription( "mysql database name" );
    o_database.setRequired( false );
    arg.addOptionR( &o_database );

    Arg::StringOption o_table( "t" );
    o_table.addName( "table" );
    o_table.setDescription( "data table (default: measurements)" );
    o_table.setRequired( false );
    arg.addOptionR( &o_table );

    Arg::StringOption o_state_table( "s" );
    o_state_table.addName( "state-table" );
    o_state_table.setDescription( "offset state table (default: import_state)" );
    o_state_table.setRequired( false );
    arg.addOptionR( &o_state_table );

    Arg::StringOption o_state_name( "n" );
    o_state_name.addName( "state-name" );
    o_state_name.setDescription( "offset state row name (default: table name)" );
    o_state_name.setRequired( false );
    arg.addOptionR( &o_state_name );

    Arg::StringOption o_csv( "f" );
    o_csv.addName( "csv" );
    o_csv.setDescription( "csv file (default: from config or first argument)" );
    o_csv.setRequired( false );
    arg.addOptionR( &o_csv );

    Arg::IntOption o_batch( "b" );
    o_batch.addName( "batch" );
    o_batch.setDescription( "rows per transaction (default: 500)" );
    o_batch.setRequired( false );
    arg.addOptionR( &o_batch );

    Arg::StringOption o_offset( "offset" );
    o_offset.setDescription( "start at this byte offset instead of the stored one (dry-run)" );
    o_offset.setRequired( false );
    arg.addOptionR( &o_offset );

    Arg::FlagOption o_verbose( "v" );
    o_verbose.addName( "verbose" );
    o_verbose.setDescription( "print the effective settings" );
    o_verbose.setRequired( false );
    arg.addOptionR( &o_verbose );

    Arg::FlagOption o_dry_run( "dry-run" );
    o_dry_run.setDescription( "parse and count only, write nothing" );
    o_dry_run.setRequired( false );
    arg.addOptionR( &o_dry_run );

    Arg::FlagOption o_create_tables( "create-tables" );
    o_create_tables.setDescription( "create tables if they do not exist" );
    o_create_tables.setRequired( false );
    arg.addOptionR( &o_create_tables );

    Arg::FlagOption o_reset( "reset" );
    o_reset.setDescription( "forget the stored offset (import from the beginning)" );
    o_reset.setRequired( false );
    arg.addOptionR( &o_reset );

    if( !arg.parse() || o_help.getState() ) {
        usage( argv[0] );
        std::cout << arg.getHelp( 5, 20, 30, 80 ) << std::endl;
        return o_help.getState() ? 0 : 1;
    }

    try {
        // settings are read with the same infrastructure as lotr_analyzer /
        // UselessPope-Broker: Configfile2 + Section + ValueType
        const std::string config_file = o_config.isSet()
            ? *o_config.getValues()->begin()
            : std::string( "~/.pi_sensor.ini" );

        Configfile2::createDefaultInstaceWithAllModules( config_file )->read( true );

        const ConfigSectionGlobal   & cfg_global = Configfile2::get( ConfigSectionGlobal::KEY );
        const ConfigSectionDatabase & cfg_db     = Configfile2::get( ConfigSectionDatabase::KEY );
        const ConfigSectionImport   & cfg_import = Configfile2::get( ConfigSectionImport::KEY );

        std::string host        = cfg_db.Host.value;
        std::string user        = cfg_db.UserName.value;
        std::string password    = cfg_db.Password.value;
        std::string database    = cfg_db.Instance.value;
        std::string table       = cfg_import.Table.value;
        std::string state_table = cfg_import.StateTable.value;
        std::string state_name;
        std::string csv         = cfg_import.CsvFile.value;
        int         batch       = cfg_import.Batch.value;
        std::streamoff start_offset = -1;

        if( password.empty() && std::getenv( "PI_SENSOR_DB_PASSWORD" ) ) {
            password = std::getenv( "PI_SENSOR_DB_PASSWORD" );
        }

        if( o_host.isSet() )        host = *o_host.getValues()->begin();
        if( o_user.isSet() )        user = *o_user.getValues()->begin();
        if( o_password.isSet() )    password = *o_password.getValues()->begin();
        if( o_database.isSet() )    database = *o_database.getValues()->begin();
        if( o_table.isSet() )       table = *o_table.getValues()->begin();
        if( o_state_table.isSet() ) state_table = *o_state_table.getValues()->begin();
        if( o_state_name.isSet() )  state_name = *o_state_name.getValues()->begin();
        if( o_csv.isSet() )         csv = *o_csv.getValues()->begin();
        if( o_batch.isSet() )       batch = s2x<int>( *o_batch.getValues()->begin(), batch );

        if( o_verbose.getState() ) {
            std::cout << "config    : " << config_file << '\n'
                      << "log file  : " << cfg_global.LogFile.value << '\n'
                      << "mysql     : " << host << ' ' << user << " db=" << database << '\n'
                      << "table     : " << table << " (state: " << state_table << ')' << '\n'
                      << "csv       : " << csv << '\n'
                      << "batch     : " << batch << std::endl;
        }

        if( batch < 1 ) {
            batch = 1;
        }

        if( state_name.empty() ) {
            state_name = table;
        }

        if( csv.empty() ) {
            csv = argv[ argc - 1 ];
        }

        if( o_offset.isSet() ) {
            start_offset = (std::streamoff)s2x<long long>( *o_offset.getValues()->begin(), 0 );
        }

        const bool dry_run = o_dry_run.getState();

        if( dry_run ) {
            const std::streamoff start = start_offset < 0 ? 0 : start_offset;
            IncrementalLineReader reader( csv, start );

            if( !reader.is_open() ) {
                std::cerr << "cannot open: " << csv << std::endl;
                return 3;
            }

            CountingSink sink;
            ImportRunner runner( reader, sink, (std::size_t)batch );
            ImportResult res = runner.run();

            print_result( co, csv, start, res, "" );
            return res.ok ? 0 : 4;
        }

        if( database.empty() || user.empty() ) {
            std::cerr << "database and user are required (use -D/-u or a config file)" << std::endl;
            return 2;
        }

        Database db( host, user, password, database, Database::DB_MYSQL );

        if( !db ) {
            std::cerr << "cannot connect to database '" << database << "' on '"
                      << host << "': " << db.get_error() << std::endl;
            return 3;
        }

        DbImportSink sink( db, table, state_table, state_name );
        sink.setFileInfo( file_size( csv ), file_mtime( csv ) );

        if( o_create_tables.getState() && !sink.createTables() ) {
            std::cerr << "create tables failed: " << sink.error() << std::endl;
            return 3;
        }

        if( o_reset.getState() && !sink.resetState() ) {
            std::cerr << "reset failed: " << sink.error() << std::endl;
            return 3;
        }

        std::streamoff offset = 0;

        if( start_offset >= 0 ) {
            offset = start_offset;
        } else if( !sink.loadOffset( offset ) ) {
            std::cerr << "reading import state failed: " << sink.error() << std::endl;
            return 3;
        }

        IncrementalLineReader reader( csv, offset );

        if( !reader.is_open() ) {
            std::cerr << "cannot open: " << csv << std::endl;
            return 3;
        }

        ImportRunner runner( reader, sink, (std::size_t)batch );
        ImportResult res = runner.run();

        print_result( co, csv, offset, res, sink.error() );
        return res.ok ? 0 : 4;

    } catch( std::exception & err ) {
        std::cerr << "error: " << err.what() << std::endl;
        return 10;
    }
}
